
local function getOrCreateFolder(parent, name)
    local f = parent:FindFirstChild(name)
    if not f then
        f = Instance.new("Folder")
        f.Name = name
        f.Parent = parent
    end
    return f
end

local function setScript(parent, name, className, source)
    local s = parent:FindFirstChild(name)
    if not s or s.ClassName ~= className then
        if s then s:Destroy() end
        s = Instance.new(className)
        s.Name = name
        s.Parent = parent
    end
    s.Source = source
    return s
end

setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "CameraController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: CameraController.lua\n    Manages trauma-based camera shakes, FOV shifts during closing rush,\n    and comedic stumble punch-ins with full accessibility toggle support.\n]]\n\nlocal Workspace = game:GetService(\"Workspace\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal CameraController = {\n    Name = \"CameraController\",\n}\n\nlocal controllers: { [string]: any } = {}\nlocal camera: Camera? = Workspace.CurrentCamera\n\n-- Camera Shake Parameters\nlocal trauma: number = 0\nlocal TRAUMA_DECAY_RATE: number = 1.8\nlocal MAX_TRANSLATION_STUDS: number = 1.2\nlocal MAX_ROTATION_DEGREES: number = 3.5\n\n-- FOV Parameters\nlocal DEFAULT_FOV: number = 70\nlocal CLOSING_RUSH_FOV: number = 82\nlocal currentFov: number = DEFAULT_FOV\nlocal targetBaseFov: number = DEFAULT_FOV\nlocal fovPunchOffset: number = 0\nlocal FOV_LERP_SPEED: number = 6.0\nlocal PUNCH_DECAY_SPEED: number = 8.0\n\n-- Perlin noise seed\nlocal noiseTime: number = 0\n\nfunction CameraController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\nend\n\nfunction CameraController:Start()\n    camera = Workspace.CurrentCamera\n    if camera then\n        currentFov = camera.FieldOfView\n    end\n\n    RunService.RenderStepped:Connect(function(deltaTime: number)\n        if not camera then\n            camera = Workspace.CurrentCamera\n            if not camera then\n                return\n            end\n        end\n\n        local uiCtrl = controllers[\"UIController\"]\n        local isShakeEnabled = true\n        if uiCtrl and typeof(uiCtrl.IsScreenShakeEnabled) == \"function\" then\n            isShakeEnabled = uiCtrl:IsScreenShakeEnabled()\n        end\n\n        -- 1. Trauma decay and shake calculation\n        if trauma > 0 then\n            trauma = math.max(0, trauma - (deltaTime * TRAUMA_DECAY_RATE))\n\n            if isShakeEnabled and trauma > 0.01 then\n                noiseTime = noiseTime + (deltaTime * 35.0)\n                local shakeFactor = trauma * trauma -- Quadratic falloff for physical punch\n\n                local offsetX = (math.noise(noiseTime, 0, 0) or 0) * MAX_TRANSLATION_STUDS * shakeFactor\n                local offsetY = (math.noise(0, noiseTime, 0) or 0) * MAX_TRANSLATION_STUDS * shakeFactor\n                local offsetZ = (math.noise(0, 0, noiseTime) or 0) * (MAX_TRANSLATION_STUDS * 0.5) * shakeFactor\n\n                local rotX = math.rad((math.noise(noiseTime + 10, 0, 0) or 0) * MAX_ROTATION_DEGREES * shakeFactor)\n                local rotY = math.rad((math.noise(0, noiseTime + 10, 0) or 0) * MAX_ROTATION_DEGREES * shakeFactor)\n                local rotZ = math.rad((math.noise(0, 0, noiseTime + 10) or 0) * (MAX_ROTATION_DEGREES * 1.5) * shakeFactor)\n\n                local shakeCFrame = CFrame.new(offsetX, offsetY, offsetZ) * CFrame.Angles(rotX, rotY, rotZ)\n                camera.CFrame = camera.CFrame * shakeCFrame\n            end\n        end\n\n        -- 2. Dynamic FOV Smoothing\n        if math.abs(fovPunchOffset) > 0.1 then\n            fovPunchOffset = fovPunchOffset - (fovPunchOffset * math.clamp(deltaTime * PUNCH_DECAY_SPEED, 0, 1))\n        else\n            fovPunchOffset = 0\n        end\n\n        local desiredFov = targetBaseFov + fovPunchOffset\n        currentFov = currentFov + ((desiredFov - currentFov) * math.clamp(deltaTime * FOV_LERP_SPEED, 0, 1))\n        camera.FieldOfView = currentFov\n    end)\n\n    print(\"[PanicShift CameraController] Camera shake & dynamic FOV active.\")\nend\n\n-- Adds trauma to the camera [0 to 1]\nfunction CameraController:TriggerShake(intensity: number)\n    local clamped = math.clamp(intensity, 0, 1)\n    trauma = math.clamp(trauma + clamped, 0, 1)\nend\n\n-- Sets base FOV (e.g. for Closing Rush wide angle)\nfunction CameraController:SetTargetFov(fov: number)\n    targetBaseFov = math.clamp(fov, 50, 100)\nend\n\n-- Temporarily punches FOV (e.g. quick zoom punch on impact or stumble)\nfunction CameraController:PunchFov(amount: number)\n    fovPunchOffset = math.clamp(fovPunchOffset + amount, -25, 25)\nend\n\nfunction CameraController:SetClosingRushActive(active: boolean)\n    if active then\n        self:SetTargetFov(CLOSING_RUSH_FOV)\n        self:PunchFov(-6) -- Quick punch-in before widening for dramatic flair\n    else\n        self:SetTargetFov(DEFAULT_FOV)\n    end\nend\n\nreturn CameraController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "EffectsController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: EffectsController.lua\n    Client visual effects, sound dispatch, particle generation,\n    and comedic stumble/slip ragdoll reactions.\n]]\n\nlocal Players = game:GetService(\"Players\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal Workspace = game:GetService(\"Workspace\")\nlocal Debris = game:GetService(\"Debris\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\n\nlocal EffectsController = {\n    Name = \"EffectsController\",\n}\n\nlocal controllers: { [string]: any } = {}\nlocal activeLoops: { [string]: Sound } = {}\nlocal soundFolder: Folder\n\n-- Audio definition registry: primary sound asset with fallback\nexport type SoundDef = {\n    Id: string,\n    FallbackId: string?,\n    Volume: number,\n    Pitch: number,\n    Looped: boolean?,\n}\n\nlocal SOUND_CATALOG: { [string]: SoundDef } = {\n    TaskComplete = {\n        Id = \"rbxasset://sounds/electronicpingshort.wav\",\n        FallbackId = \"rbxassetid://6026947094\",\n        Volume = 0.75,\n        Pitch = 1.1,\n    },\n    CashRegister = {\n        Id = \"rbxasset://sounds/bell.wav\",\n        FallbackId = \"rbxassetid://9069609200\",\n        Volume = 0.85,\n        Pitch = 1.0,\n    },\n    DisasterTelegraph = {\n        Id = \"rbxasset://sounds/action_falling.mp3\",\n        FallbackId = \"rbxassetid://9065458027\",\n        Volume = 0.85,\n        Pitch = 0.95,\n    },\n    DisasterActive = {\n        Id = \"rbxasset://sounds/impact_glass_medium.mp3\",\n        FallbackId = \"rbxassetid://9065365518\",\n        Volume = 0.9,\n        Pitch = 0.9,\n    },\n    DisasterCleared = {\n        Id = \"rbxasset://sounds/action_get_powerup.mp3\",\n        FallbackId = \"rbxassetid://6026947094\",\n        Volume = 0.7,\n        Pitch = 1.25,\n    },\n    SlipStumble = {\n        Id = \"rbxasset://sounds/uuch.wav\",\n        FallbackId = \"rbxassetid://9114223171\",\n        Volume = 0.8,\n        Pitch = 1.15,\n    },\n    CartRattle = {\n        Id = \"rbxasset://sounds/action_footsteps_plastic.mp3\",\n        FallbackId = \"rbxassetid://9114221580\",\n        Volume = 0.5,\n        Pitch = 1.0,\n        Looped = true,\n    },\n    Sparks = {\n        Id = \"rbxasset://sounds/electronicpingshort.wav\",\n        FallbackId = \"rbxassetid://9114223842\",\n        Volume = 0.65,\n        Pitch = 1.3,\n    },\n    ButtonClick = {\n        Id = \"rbxasset://sounds/button.wav\",\n        FallbackId = \"rbxassetid://6895079853\",\n        Volume = 0.45,\n        Pitch = 1.1,\n    },\n    RushSiren = {\n        Id = \"rbxasset://sounds/action_jump.mp3\",\n        FallbackId = \"rbxassetid://9065458027\",\n        Volume = 0.8,\n        Pitch = 1.05,\n    },\n}\n\nfunction EffectsController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\n\n    soundFolder = Instance.new(\"Folder\")\n    soundFolder.Name = \"PanicShiftClientAudio\"\n    soundFolder.Parent = SoundService\nend\n\nfunction EffectsController:Start()\n    print(\"[PanicShift EffectsController] Audio, Particle & Animation systems active.\")\nend\n\n-- ====================================================================\n-- AUDIO DISPATCHER\n-- ====================================================================\n\nfunction EffectsController:PlaySound(\n    soundName: string,\n    targetPositionOrPart: (Vector3 | Instance)?,\n    customOptions: { Volume: number?, Pitch: number?, Looped: boolean? }?\n): Sound?\n    local soundDef = SOUND_CATALOG[soundName]\n    if not soundDef then\n        warn(string.format(\"[EffectsController] Unknown sound name: %s\", soundName))\n        return nil\n    end\n\n    local sound = Instance.new(\"Sound\")\n    sound.Name = soundName\n    sound.SoundId = soundDef.Id\n    sound.Volume = if customOptions and customOptions.Volume ~= nil then customOptions.Volume else soundDef.Volume\n    \n    -- Slight natural pitch variation for organic party game feel (±5%)\n    local basePitch = if customOptions and customOptions.Pitch ~= nil then customOptions.Pitch else soundDef.Pitch\n    local pitchVariation = (math.random(95, 105) / 100)\n    sound.PlaybackSpeed = math.clamp(basePitch * pitchVariation, 0.5, 2.0)\n    sound.Looped = if customOptions and customOptions.Looped ~= nil then customOptions.Looped else (soundDef.Looped or false)\n\n    if targetPositionOrPart then\n        if typeof(targetPositionOrPart) == \"Vector3\" then\n            local attachment = Instance.new(\"Attachment\")\n            attachment.WorldPosition = targetPositionOrPart\n            attachment.Parent = Workspace.Terrain\n            sound.Parent = attachment\n            \n            sound.Ended:Connect(function()\n                attachment:Destroy()\n            end)\n        elseif typeof(targetPositionOrPart) == \"Instance\" then\n            sound.Parent = targetPositionOrPart\n        end\n    else\n        sound.Parent = soundFolder\n    end\n\n    sound:Play()\n\n    if not sound.Looped then\n        sound.Ended:Connect(function()\n            sound:Destroy()\n        end)\n        -- Hard cleanup failsafe\n        Debris:AddItem(sound, 8)\n    else\n        activeLoops[soundName] = sound\n    end\n\n    return sound\nend\n\nfunction EffectsController:StopSound(soundName: string)\n    local active = activeLoops[soundName]\n    if active then\n        active:Stop()\n        active:Destroy()\n        activeLoops[soundName] = nil\n    end\nend\n\nfunction EffectsController:PlayButtonClick()\n    self:PlaySound(\"ButtonClick\")\nend\n\nfunction EffectsController:PlayCreditSound()\n    self:PlaySound(\"CashRegister\")\nend\n\nfunction EffectsController:PlayTaskSuccess(taskType: string, position: Vector3?)\n    self:PlaySound(\"TaskComplete\", position)\n    if position then\n        self:EmitTaskSuccess(position)\n    end\nend\n\nfunction EffectsController:PlayDisasterAudio(disasterId: string, status: string)\n    if status == Constants.DisasterStatus.TELEGRAPH then\n        self:PlaySound(\"DisasterTelegraph\")\n    elseif status == Constants.DisasterStatus.ACTIVE then\n        self:PlaySound(\"DisasterActive\")\n        if disasterId == Constants.Disasters.RUNAWAY_CARTS then\n            self:PlaySound(\"CartRattle\", nil, { Looped = true })\n        elseif disasterId == Constants.Disasters.BLACKOUT then\n            self:PlaySound(\"Sparks\")\n        end\n    elseif status == Constants.DisasterStatus.COMPLETED or status == Constants.DisasterStatus.CANCELLED then\n        self:StopSound(\"CartRattle\")\n        self:PlaySound(\"DisasterCleared\")\n    end\nend\n\n-- ====================================================================\n-- PROCEDURAL PARTICLES\n-- ====================================================================\n\n-- Bursts celebratory stars / sparkles at completed task location\nfunction EffectsController:EmitTaskSuccess(worldPosition: Vector3)\n    local attachment = Instance.new(\"Attachment\")\n    attachment.WorldPosition = worldPosition + Vector3.new(0, 1.5, 0)\n    attachment.Parent = Workspace.Terrain\n\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"TaskSuccessSparkles\"\n    emitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    emitter.Color = ColorSequence.new({\n        ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 230, 80)),\n        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(50, 255, 150)),\n        ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),\n    })\n    emitter.Size = NumberSequence.new({\n        NumberSequenceKeypoint.new(0, 0.4),\n        NumberSequenceKeypoint.new(0.5, 1.2),\n        NumberSequenceKeypoint.new(1, 0),\n    })\n    emitter.Transparency = NumberSequence.new({\n        NumberSequenceKeypoint.new(0, 0),\n        NumberSequenceKeypoint.new(0.8, 0.2),\n        NumberSequenceKeypoint.new(1, 1),\n    })\n    emitter.Speed = NumberRange.new(4, 9)\n    emitter.SpreadAngle = Vector2.new(180, 180)\n    emitter.Lifetime = NumberRange.new(0.6, 1.2)\n    emitter.Rate = 0\n    emitter.LightEmission = 0.8\n    emitter.Parent = attachment\n\n    emitter:Emit(25)\n    Debris:AddItem(attachment, 1.5)\nend\n\n-- Attaches gentle bubbles to spill areas\nfunction EffectsController:CreateSpillBubbles(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"SpillBubbles\"\n    emitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(130, 225, 255), Color3.fromRGB(80, 190, 240))\n    emitter.Size = NumberSequence.new(0.3, 0.8)\n    emitter.Transparency = NumberSequence.new(0.2, 0.8)\n    emitter.Lifetime = NumberRange.new(1.0, 2.0)\n    emitter.Speed = NumberRange.new(1.5, 3.5)\n    emitter.Rate = 8\n    emitter.Acceleration = Vector3.new(0, 2, 0)\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- Attaches electrical spark bursts to breaker and maintenance panels\nfunction EffectsController:CreateBreakerSparks(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"BreakerSparks\"\n    emitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(255, 240, 120), Color3.fromRGB(255, 140, 20))\n    emitter.Size = NumberSequence.new(0.2, 0.6)\n    emitter.Speed = NumberRange.new(6, 14)\n    emitter.SpreadAngle = Vector2.new(60, 60)\n    emitter.Lifetime = NumberRange.new(0.2, 0.5)\n    emitter.Rate = 12\n    emitter.Acceleration = Vector3.new(0, -20, 0)\n    emitter.LightEmission = 1.0\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- Attaches slippery foam particles for soap disaster\nfunction EffectsController:CreateSoapFoam(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"SoapFoam\"\n    emitter.Texture = \"rbxasset://textures/particles/smoke_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(240, 250, 255))\n    emitter.Size = NumberSequence.new(0.6, 1.4)\n    emitter.Transparency = NumberSequence.new(0.3, 0.9)\n    emitter.Lifetime = NumberRange.new(1.0, 1.8)\n    emitter.Speed = NumberRange.new(0.5, 1.5)\n    emitter.Rate = 10\n    emitter.SpreadAngle = Vector2.new(180, 180)\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- Attaches dust cloud puff for avalanche collapses\nfunction EffectsController:CreateAvalancheDust(parentPart: BasePart): ParticleEmitter\n    local emitter = Instance.new(\"ParticleEmitter\")\n    emitter.Name = \"AvalancheDust\"\n    emitter.Texture = \"rbxasset://textures/particles/smoke_main.dds\"\n    emitter.Color = ColorSequence.new(Color3.fromRGB(190, 175, 160))\n    emitter.Size = NumberSequence.new(1.5, 4.0)\n    emitter.Transparency = NumberSequence.new(0.2, 1.0)\n    emitter.Lifetime = NumberRange.new(1.2, 2.4)\n    emitter.Speed = NumberRange.new(4, 10)\n    emitter.SpreadAngle = Vector2.new(180, 180)\n    emitter.Rate = 20\n    emitter.Parent = parentPart\n    return emitter\nend\n\n-- ====================================================================\n-- PROCEDURAL CHARACTER STUMBLES / PHYSICAL COMEDY (FR-12)\n-- ====================================================================\n\n-- Plays a temporary stumble/slip ragdoll reaction\nfunction EffectsController:PlayStumbleReaction(duration: number, knockbackVelocity: Vector3?)\n    local localPlayer = Players.LocalPlayer\n    local character = localPlayer.Character\n    if not character then\n        return\n    end\n\n    local humanoid = character:FindFirstChildOfClass(\"Humanoid\")\n    local rootPart = character:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n    if not humanoid or not rootPart then\n        return\n    end\n\n    -- Trigger stumble sound & camera shock\n    self:PlaySound(\"SlipStumble\", rootPart.Position)\n    local cameraCtrl = controllers[\"CameraController\"]\n    if cameraCtrl and typeof(cameraCtrl.TriggerShake) == \"function\" then\n        cameraCtrl:TriggerShake(0.75)\n    end\n\n    -- Apply comedic knockback impulse\n    if knockbackVelocity then\n        rootPart.AssemblyLinearVelocity = knockbackVelocity\n    else\n        local randomImpulse = Vector3.new(\n            math.random(-25, 25),\n            math.random(15, 30),\n            math.random(-25, 25)\n        )\n        rootPart.AssemblyLinearVelocity = randomImpulse\n    end\n\n    -- Ragdoll stumble state\n    humanoid.PlatformStand = true\n\n    local safeDuration = math.clamp(duration, 0.4, 2.5)\n    task.delay(safeDuration, function()\n        if humanoid and humanoid.Parent then\n            humanoid.PlatformStand = false\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end\n    end)\nend\n\nreturn EffectsController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "InputController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: InputController.lua\n    Unified cross-platform input manager (Keyboard, Touch, Gamepad).\n    Handles action bindings for Interact, Sprint, Emote, Shop Toggle,\n    and Gamepad B/Keyboard Escape modal dismissal.\n]]\n\nlocal ContextActionService = game:GetService(\"ContextActionService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal Players = game:GetService(\"Players\")\n\nlocal InputController = {\n    Name = \"InputController\",\n}\n\nlocal controllers: { [string]: any } = {}\n\nlocal ACTION_INTERACT = \"PanicShift_Interact\"\nlocal ACTION_SPRINT = \"PanicShift_Sprint\"\nlocal ACTION_TOGGLE_SHOP = \"PanicShift_ToggleShop\"\nlocal ACTION_CLOSE_MODAL = \"PanicShift_CloseModal\"\n\nfunction InputController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\nend\n\nfunction InputController:Start()\n    print(\"[PanicShift InputController] Binding cross-platform actions (PC, Touch, Gamepad)...\")\n\n    -- 1. Bind Interact (E / ButtonX / Mobile Touch Button)\n    ContextActionService:BindAction(\n        ACTION_INTERACT,\n        function(actionName, inputState, inputObject)\n            if inputState == Enum.UserInputState.Begin then\n                if controllers.InteractionController then\n                    controllers.InteractionController:TriggerCurrentInteraction()\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        true, -- Generates mobile touch button\n        Enum.KeyCode.E,\n        Enum.KeyCode.ButtonX\n    )\n    ContextActionService:SetTitle(ACTION_INTERACT, \"Interact\")\n    ContextActionService:SetPosition(ACTION_INTERACT, UDim2.new(1, -120, 1, -140))\n\n    -- 2. Bind Sprint (LeftShift / Gamepad L3)\n    ContextActionService:BindAction(\n        ACTION_SPRINT,\n        function(actionName, inputState, inputObject)\n            local character = Players.LocalPlayer.Character\n            local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n            if humanoid then\n                if inputState == Enum.UserInputState.Begin then\n                    humanoid.WalkSpeed = 24 -- Sprint speed\n                elseif inputState == Enum.UserInputState.End then\n                    humanoid.WalkSpeed = 16 -- Normal speed\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        false,\n        Enum.KeyCode.LeftShift,\n        Enum.KeyCode.ButtonL3\n    )\n\n    -- 3. Bind Toggle Shop (M / Gamepad ButtonY)\n    ContextActionService:BindAction(\n        ACTION_TOGGLE_SHOP,\n        function(actionName, inputState, inputObject)\n            if inputState == Enum.UserInputState.Begin then\n                local uiCtrl = controllers.UIController\n                if uiCtrl and uiCtrl.ToggleShop then\n                    uiCtrl:ToggleShop()\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        false,\n        Enum.KeyCode.M,\n        Enum.KeyCode.ButtonY\n    )\n\n    -- 4. Bind Modal Dismissal (Escape / Gamepad ButtonB)\n    ContextActionService:BindAction(\n        ACTION_CLOSE_MODAL,\n        function(actionName, inputState, inputObject)\n            if inputState == Enum.UserInputState.Begin then\n                local playerGui = Players.LocalPlayer:FindFirstChild(\"PlayerGui\")\n                local gui = playerGui and playerGui:FindFirstChild(\"PanicShiftGui\")\n                if gui then\n                    local shop = gui:FindFirstChild(\"ShopModal\")\n                    if shop and shop.Visible then shop.Visible = false return Enum.ContextActionResult.Sink end\n                    local ch = gui:FindFirstChild(\"ChallengesModal\")\n                    if ch and ch.Visible then ch.Visible = false return Enum.ContextActionResult.Sink end\n                    local st = gui:FindFirstChild(\"SettingsModal\")\n                    if st and st.Visible then st.Visible = false return Enum.ContextActionResult.Sink end\n                    local res = gui:FindFirstChild(\"ResultsModal\")\n                    if res and res.Visible then res.Visible = false return Enum.ContextActionResult.Sink end\n                end\n            end\n            return Enum.ContextActionResult.Pass\n        end,\n        false,\n        Enum.KeyCode.Escape,\n        Enum.KeyCode.ButtonB\n    )\nend\n\nfunction InputController:IsTouchDevice(): boolean\n    return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled\nend\n\nfunction InputController:IsGamepadConnected(): boolean\n    return UserInputService.GamepadEnabled\nend\n\nreturn InputController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "InteractionController", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: InteractionController.lua\n    Client raycasting, prompt detection, task interaction dispatcher,\n    and audiovisual feedback trigger.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal Shared = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"PanicShiftShared\")\nlocal Types = require(Shared:WaitForChild(\"Types\"))\nlocal Constants = require(Shared:WaitForChild(\"Constants\"))\nlocal Network = require(Shared:WaitForChild(\"Network\"))\n\nlocal InteractionController = {\n    Name = \"InteractionController\",\n}\n\nlocal controllers: { [string]: any } = {}\nlocal currentFocusedTaskId: string? = nil\nlocal knownClientTasks: { [string]: any } = {}\n\nfunction InteractionController:Init(controllerRegistry: { [string]: any })\n    controllers = controllerRegistry\nend\n\nfunction InteractionController:Start()\n    local taskStateRemote = Network.GetRemoteEvent(Constants.Remotes.TASK_STATE_CHANGED)\n    taskStateRemote.OnClientEvent:Connect(function(taskId: string, eventType: string, data: any)\n        if eventType == \"CREATED\" then\n            knownClientTasks[taskId] = data\n        elseif eventType == \"COMPLETED\" or eventType == \"CLEARED\" then\n            knownClientTasks[taskId] = nil\n            if currentFocusedTaskId == taskId then\n                currentFocusedTaskId = nil\n            end\n        end\n    end)\nend\n\nfunction InteractionController:SetFocusedTask(taskId: string?)\n    currentFocusedTaskId = taskId\nend\n\nfunction InteractionController:TriggerCurrentInteraction(): ()\n    local taskId: string? = currentFocusedTaskId\n\n    -- If no focused task, automatically find nearest interactive task or anchor\n    if not taskId then\n        local character = Players.LocalPlayer.Character\n        local rootPart = character and character:FindFirstChild(\"HumanoidRootPart\") :: BasePart?\n        if rootPart then\n            local myPos = rootPart.Position\n            local closestDist = Constants.MAX_INTERACTION_DISTANCE\n\n            -- 1. Check known replicated tasks\n            for id, data in pairs(knownClientTasks) do\n                if data and data.Position then\n                    local dist = (data.Position - myPos).Magnitude\n                    if dist <= closestDist then\n                        closestDist = dist\n                        taskId = id\n                    end\n                end\n            end\n\n            -- 2. Check physical TaskAnchors or SupermarketTasks in Workspace\n            if not taskId then\n                local map = game:GetService(\"Workspace\"):FindFirstChild(\"SupermarketMap\")\n                local anchors = map and map:FindFirstChild(\"TaskAnchors\")\n                if anchors then\n                    for _, anchor in ipairs(anchors:GetChildren()) do\n                        if anchor:IsA(\"BasePart\") then\n                            local dist = (anchor.Position - myPos).Magnitude\n                            if dist <= closestDist then\n                                closestDist = dist\n                                taskId = anchor.Name\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    if not taskId then\n        return\n    end\n    local taskInfo = knownClientTasks[taskId]\n    local requestFunc = Network.GetRemoteFunction(Constants.Remotes.REQUEST_TASK_ACTION)\n    local response: Types.NetworkResponse = requestFunc:InvokeServer(taskId, \"INTERACT\")\n\n    if response.Success then\n        print(string.format(\"[Interaction] Completed task %s successfully!\", taskId))\n        currentFocusedTaskId = nil\n\n        -- Milestone 8: Trigger positive task completion effects\n        local effectsCtrl = controllers[\"EffectsController\"]\n        local cameraCtrl = controllers[\"CameraController\"]\n\n        local taskType = if taskInfo and taskInfo.Type then taskInfo.Type else \"RESTOCK\"\n        local worldPos: Vector3? = nil\n\n        local character = Players.LocalPlayer.Character\n        if character and character:FindFirstChild(\"HumanoidRootPart\") then\n            worldPos = (character:FindFirstChild(\"HumanoidRootPart\") :: BasePart).Position\n        end\n\n        if effectsCtrl and typeof(effectsCtrl.PlayTaskSuccess) == \"function\" then\n            effectsCtrl:PlayTaskSuccess(taskType, worldPos)\n        end\n\n        if cameraCtrl then\n            if typeof(cameraCtrl.TriggerShake) == \"function\" then\n                cameraCtrl:TriggerShake(0.15)\n            end\n            if typeof(cameraCtrl.PunchFov) == \"function\" then\n                cameraCtrl:PunchFov(2.0)\n            end\n        end\n    else\n        warn(string.format(\"[Interaction] Task rejected: %s (%s)\", response.Message or \"\", response.ErrorCode))\n    end\nend\n\nreturn InteractionController\n")
setScript(getOrCreateFolder(game:GetService("StarterPlayer"):WaitForChild("StarterPlayerScripts"), "Controllers"), "UIBuilder", "ModuleScript", "--!strict\n--[[\n    PANIC SHIFT: UIBuilder.lua\n    Procedural UI builder creating the complete responsive ScreenGui hierarchy.\n    Includes Shift HUD, Disaster Alert Banners, Results Modal, Cosmetic Shop,\n    Daily Challenges Drawer, and Settings.\n]]\n\nlocal Players = game:GetService(\"Players\")\n\nlocal UIBuilder = {}\n\nlocal COLORS = {\n    BRAND_GREEN = Color3.fromRGB(26, 120, 68),\n    BRAND_ORANGE = Color3.fromRGB(235, 95, 20),\n    BRAND_YELLOW = Color3.fromRGB(250, 200, 30),\n    DARK_BG = Color3.fromRGB(22, 25, 34),\n    CARD_BG = Color3.fromRGB(32, 36, 48),\n    CARD_HOVER = Color3.fromRGB(44, 50, 66),\n    WHITE = Color3.fromRGB(255, 255, 255),\n    GRAY_TEXT = Color3.fromRGB(180, 185, 200),\n    DANGER_RED = Color3.fromRGB(235, 50, 50),\n    SUCCESS_GREEN = Color3.fromRGB(40, 200, 90),\n}\n\nlocal FONT_BOLD = Enum.Font.FredokaOne\nlocal FONT_REGULAR = Enum.Font.GothamMedium\n\nlocal function createCorner(parent: Instance, radius: number): UICorner\n    local corner = Instance.new(\"UICorner\")\n    corner.CornerRadius = UDim.new(0, radius)\n    corner.Parent = parent\n    return corner\nend\n\nlocal function createStroke(parent: Instance, color: Color3, thickness: number): UIStroke\n    local stroke = Instance.new(\"UIStroke\")\n    stroke.Color = color\n    stroke.Thickness = thickness\n    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n    stroke.Parent = parent\n    return stroke\nend\n\nfunction UIBuilder.Build(playerGui: PlayerGui): { [string]: any }\n    -- Clear any old GUI\n    for _, child in ipairs(playerGui:GetChildren()) do\n        if child.Name == \"PanicShiftGui\" then\n            child:Destroy()\n        end\n    end\n\n    local screenGui = Instance.new(\"ScreenGui\")\n    screenGui.Name = \"PanicShiftGui\"\n    screenGui.ResetOnSpawn = false\n    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling\n    screenGui.Parent = playerGui\n\n    local refs: { [string]: any } = {\n        ScreenGui = screenGui,\n    }\n\n    -- =========================================================================\n    -- 1. TOP CENTER: SHIFT HUD (Timer & Quota Progress)\n    -- =========================================================================\n    local topCenterFrame = Instance.new(\"Frame\")\n    topCenterFrame.Name = \"TopCenter_ShiftHeader\"\n    topCenterFrame.Size = UDim2.new(0, 340, 0, 84)\n    topCenterFrame.Position = UDim2.new(0.5, -170, 0, 16)\n    topCenterFrame.BackgroundColor3 = COLORS.DARK_BG\n    topCenterFrame.BackgroundTransparency = 0.15\n    topCenterFrame.BorderSizePixel = 0\n    topCenterFrame.Parent = screenGui\n    createCorner(topCenterFrame, 14)\n    createStroke(topCenterFrame, Color3.fromRGB(50, 55, 75), 1.5)\n\n    local shiftTimerLabel = Instance.new(\"TextLabel\")\n    shiftTimerLabel.Name = \"ShiftTimerLabel\"\n    shiftTimerLabel.Size = UDim2.new(0, 100, 0, 34)\n    shiftTimerLabel.Position = UDim2.new(0, 12, 0, 6)\n    shiftTimerLabel.BackgroundTransparency = 1\n    shiftTimerLabel.Text = \"03:00\"\n    shiftTimerLabel.TextColor3 = COLORS.WHITE\n    shiftTimerLabel.Font = FONT_BOLD\n    shiftTimerLabel.TextSize = 28\n    shiftTimerLabel.TextXAlignment = Enum.TextXAlignment.Left\n    shiftTimerLabel.Parent = topCenterFrame\n    refs.ShiftTimerLabel = shiftTimerLabel\n\n    local shiftStateBadge = Instance.new(\"TextLabel\")\n    shiftStateBadge.Name = \"ShiftStateBadge\"\n    shiftStateBadge.Size = UDim2.new(0, 200, 0, 24)\n    shiftStateBadge.Position = UDim2.new(1, -212, 0, 10)\n    shiftStateBadge.BackgroundColor3 = COLORS.BRAND_GREEN\n    shiftStateBadge.Text = \"ACTIVE SHIFT\"\n    shiftStateBadge.TextColor3 = COLORS.WHITE\n    shiftStateBadge.Font = FONT_BOLD\n    shiftStateBadge.TextSize = 13\n    shiftStateBadge.Parent = topCenterFrame\n    createCorner(shiftStateBadge, 6)\n    refs.ShiftStateBadge = shiftStateBadge\n\n    -- Quota Bar Container\n    local quotaContainer = Instance.new(\"Frame\")\n    quotaContainer.Name = \"QuotaContainer\"\n    quotaContainer.Size = UDim2.new(1, -24, 0, 28)\n    quotaContainer.Position = UDim2.new(0, 12, 1, -38)\n    quotaContainer.BackgroundTransparency = 1\n    quotaContainer.Parent = topCenterFrame\n\n    local quotaBarBg = Instance.new(\"Frame\")\n    quotaBarBg.Name = \"QuotaBarBg\"\n    quotaBarBg.Size = UDim2.new(1, 0, 1, 0)\n    quotaBarBg.BackgroundColor3 = Color3.fromRGB(35, 40, 55)\n    quotaBarBg.BorderSizePixel = 0\n    quotaBarBg.Parent = quotaContainer\n    createCorner(quotaBarBg, 8)\n\n    local quotaBarFill = Instance.new(\"Frame\")\n    quotaBarFill.Name = \"QuotaBarFill\"\n    quotaBarFill.Size = UDim2.new(0.4, 0, 1, 0)\n    quotaBarFill.BackgroundColor3 = COLORS.BRAND_ORANGE\n    quotaBarFill.BorderSizePixel = 0\n    quotaBarFill.Parent = quotaBarBg\n    createCorner(quotaBarFill, 8)\n    refs.QuotaBarFill = quotaBarFill\n\n    local quotaLabel = Instance.new(\"TextLabel\")\n    quotaLabel.Name = \"QuotaLabel\"\n    quotaLabel.Size = UDim2.new(1, 0, 1, 0)\n    quotaLabel.BackgroundTransparency = 1\n    quotaLabel.Text = \"STORE QUOTA: 10 / 25\"\n    quotaLabel.TextColor3 = COLORS.WHITE\n    quotaLabel.Font = FONT_BOLD\n    quotaLabel.TextSize = 14\n    quotaLabel.ZIndex = 3\n    quotaLabel.Parent = quotaContainer\n    refs.QuotaLabel = quotaLabel\n\n    -- =========================================================================\n    -- 2. TOP RIGHT: PLAYER WALLET & XP\n    -- =========================================================================\n    local walletFrame = Instance.new(\"Frame\")\n    walletFrame.Name = \"TopRight_PlayerWallet\"\n    walletFrame.Size = UDim2.new(0, 220, 0, 68)\n    walletFrame.Position = UDim2.new(1, -236, 0, 16)\n    walletFrame.BackgroundColor3 = COLORS.DARK_BG\n    walletFrame.BackgroundTransparency = 0.15\n    walletFrame.BorderSizePixel = 0\n    walletFrame.Parent = screenGui\n    createCorner(walletFrame, 12)\n    createStroke(walletFrame, Color3.fromRGB(50, 55, 75), 1.5)\n\n    local creditLabel = Instance.new(\"TextLabel\")\n    creditLabel.Name = \"CreditLabel\"\n    creditLabel.Size = UDim2.new(1, -70, 0, 28)\n    creditLabel.Position = UDim2.new(0, 14, 0, 8)\n    creditLabel.BackgroundTransparency = 1\n    creditLabel.Text = \"💰 0 CREDITS\"\n    creditLabel.TextColor3 = COLORS.BRAND_YELLOW\n    creditLabel.Font = FONT_BOLD\n    creditLabel.TextSize = 16\n    creditLabel.TextXAlignment = Enum.TextXAlignment.Left\n    creditLabel.Parent = walletFrame\n    refs.CreditLabel = creditLabel\n\n    local levelBadge = Instance.new(\"TextLabel\")\n    levelBadge.Name = \"LevelBadge\"\n    levelBadge.Size = UDim2.new(0, 48, 0, 26)\n    levelBadge.Position = UDim2.new(1, -58, 0, 8)\n    levelBadge.BackgroundColor3 = COLORS.BRAND_ORANGE\n    levelBadge.Text = \"LVL 1\"\n    levelBadge.TextColor3 = COLORS.WHITE\n    levelBadge.Font = FONT_BOLD\n    levelBadge.TextSize = 13\n    levelBadge.Parent = walletFrame\n    createCorner(levelBadge, 6)\n    refs.LevelBadge = levelBadge\n\n    local xpBarBg = Instance.new(\"Frame\")\n    xpBarBg.Name = \"XpBarBg\"\n    xpBarBg.Size = UDim2.new(1, -28, 0, 12)\n    xpBarBg.Position = UDim2.new(0, 14, 1, -22)\n    xpBarBg.BackgroundColor3 = Color3.fromRGB(35, 40, 55)\n    xpBarBg.BorderSizePixel = 0\n    xpBarBg.Parent = walletFrame\n    createCorner(xpBarBg, 6)\n\n    local xpBarFill = Instance.new(\"Frame\")\n    xpBarFill.Name = \"XpBarFill\"\n    xpBarFill.Size = UDim2.new(0.2, 0, 1, 0)\n    xpBarFill.BackgroundColor3 = Color3.fromRGB(60, 160, 255)\n    xpBarFill.BorderSizePixel = 0\n    xpBarFill.Parent = xpBarBg\n    createCorner(xpBarFill, 6)\n    refs.XpBarFill = xpBarFill\n\n    -- =========================================================================\n    -- 3. BOTTOM LEFT: ACTION DRAWER (Shop, Challenges, Settings)\n    -- =========================================================================\n    local drawerFrame = Instance.new(\"Frame\")\n    drawerFrame.Name = \"BottomLeft_ActionDrawer\"\n    drawerFrame.Size = UDim2.new(0, 310, 0, 48)\n    drawerFrame.Position = UDim2.new(0, 16, 1, -64)\n    drawerFrame.BackgroundTransparency = 1\n    drawerFrame.Parent = screenGui\n\n    local function createActionButton(name: string, text: string, xOffset: number, color: Color3): TextButton\n        local btn = Instance.new(\"TextButton\")\n        btn.Name = name\n        btn.Size = UDim2.new(0, 96, 1, 0)\n        btn.Position = UDim2.new(0, xOffset, 0, 0)\n        btn.BackgroundColor3 = color\n        btn.Text = text\n        btn.TextColor3 = COLORS.WHITE\n        btn.Font = FONT_BOLD\n        btn.TextSize = 12\n        btn.Parent = drawerFrame\n        createCorner(btn, 10)\n        createStroke(btn, Color3.fromRGB(50, 55, 75), 1)\n        return btn\n    end\n\n    refs.ShopBtn = createActionButton(\"ShopBtn\", \"🛍️ SHOP\", 0, COLORS.BRAND_GREEN)\n    refs.ChallengesBtn = createActionButton(\"ChallengesBtn\", \"📋 QUESTS\", 104, Color3.fromRGB(40, 110, 190))\n    refs.SettingsBtn = createActionButton(\"SettingsBtn\", \"⚙️ CONFIG\", 208, Color3.fromRGB(50, 55, 70))\n\n    -- =========================================================================\n    -- 4. CENTER: DISASTER ALERT BANNER (Animated Slide Down)\n    -- =========================================================================\n    local disasterBanner = Instance.new(\"Frame\")\n    disasterBanner.Name = \"DisasterAlertBanner\"\n    disasterBanner.Size = UDim2.new(0, 460, 0, 90)\n    disasterBanner.Position = UDim2.new(0.5, -230, 0, -110) -- Off-screen above\n    disasterBanner.BackgroundColor3 = Color3.fromRGB(35, 15, 20)\n    disasterBanner.BorderSizePixel = 0\n    disasterBanner.Visible = false\n    disasterBanner.Parent = screenGui\n    createCorner(disasterBanner, 14)\n    createStroke(disasterBanner, COLORS.DANGER_RED, 2.5)\n    refs.DisasterBanner = disasterBanner\n\n    local disasterTitle = Instance.new(\"TextLabel\")\n    disasterTitle.Name = \"DisasterTitle\"\n    disasterTitle.Size = UDim2.new(1, -24, 0, 36)\n    disasterTitle.Position = UDim2.new(0, 12, 0, 8)\n    disasterTitle.BackgroundTransparency = 1\n    disasterTitle.Text = \"⚠️ DISASTER WARNING!\"\n    disasterTitle.TextColor3 = COLORS.BRAND_YELLOW\n    disasterTitle.Font = FONT_BOLD\n    disasterTitle.TextSize = 22\n    disasterTitle.Parent = disasterBanner\n    refs.DisasterTitle = disasterTitle\n\n    local disasterSubtitle = Instance.new(\"TextLabel\")\n    disasterSubtitle.Name = \"DisasterSubtitle\"\n    disasterSubtitle.Size = UDim2.new(1, -24, 0, 32)\n    disasterSubtitle.Position = UDim2.new(0, 12, 0, 46)\n    disasterSubtitle.BackgroundTransparency = 1\n    disasterSubtitle.Text = \"Rogue carts detected! Seek safe aisles immediately!\"\n    disasterSubtitle.TextColor3 = COLORS.WHITE\n    disasterSubtitle.Font = FONT_REGULAR\n    disasterSubtitle.TextSize = 14\n    disasterSubtitle.Parent = disasterBanner\n    refs.DisasterSubtitle = disasterSubtitle\n\n    -- =========================================================================\n    -- 5. CENTER: RESULTS MODAL (End of Shift Paycheck)\n    -- =========================================================================\n    local resultsModal = Instance.new(\"Frame\")\n    resultsModal.Name = \"ResultsModal\"\n    resultsModal.Size = UDim2.new(0, 480, 0, 360)\n    resultsModal.Position = UDim2.new(0.5, -240, 0.5, -180)\n    resultsModal.BackgroundColor3 = COLORS.DARK_BG\n    resultsModal.BorderSizePixel = 0\n    resultsModal.Visible = false\n    resultsModal.ZIndex = 10\n    resultsModal.Parent = screenGui\n    createCorner(resultsModal, 16)\n    createStroke(resultsModal, COLORS.BRAND_ORANGE, 2.5)\n    refs.ResultsModal = resultsModal\n\n    local resultsTitle = Instance.new(\"TextLabel\")\n    resultsTitle.Name = \"ResultsTitle\"\n    resultsTitle.Size = UDim2.new(1, -30, 0, 50)\n    resultsTitle.Position = UDim2.new(0, 15, 0, 15)\n    resultsTitle.BackgroundTransparency = 1\n    resultsTitle.Text = \"🎉 SHIFT SURVIVED!\"\n    resultsTitle.TextColor3 = COLORS.BRAND_YELLOW\n    resultsTitle.Font = FONT_BOLD\n    resultsTitle.TextSize = 30\n    resultsTitle.ZIndex = 11\n    resultsTitle.Parent = resultsModal\n    refs.ResultsTitle = resultsTitle\n\n    local resultsDetails = Instance.new(\"TextLabel\")\n    resultsDetails.Name = \"ResultsDetails\"\n    resultsDetails.Size = UDim2.new(1, -40, 0, 190)\n    resultsDetails.Position = UDim2.new(0, 20, 0, 75)\n    resultsDetails.BackgroundColor3 = COLORS.CARD_BG\n    resultsDetails.Text = \"Paycheck Summary:\\n\\n• Team Quota Reached: 25 / 25\\n• Base Shift Pay: +50 Credits\\n• MVP Bonus: +25 Credits\\n• Shift XP Earned: +60 XP\\n\\n⭐ EMPLOYEE OF THE SHIFT: Astrameld\"\n    resultsDetails.TextColor3 = COLORS.WHITE\n    resultsDetails.Font = FONT_REGULAR\n    resultsDetails.TextSize = 16\n    resultsDetails.ZIndex = 11\n    resultsDetails.Parent = resultsModal\n    createCorner(resultsDetails, 12)\n    refs.ResultsDetails = resultsDetails\n\n    local resultsCloseBtn = Instance.new(\"TextButton\")\n    resultsCloseBtn.Name = \"ResultsCloseBtn\"\n    resultsCloseBtn.Size = UDim2.new(0, 220, 0, 46)\n    resultsCloseBtn.Position = UDim2.new(0.5, -110, 1, -62)\n    resultsCloseBtn.BackgroundColor3 = COLORS.BRAND_GREEN\n    resultsCloseBtn.Text = \"CONTINUE TO BREAKROOM\"\n    resultsCloseBtn.TextColor3 = COLORS.WHITE\n    resultsCloseBtn.Font = FONT_BOLD\n    resultsCloseBtn.TextSize = 14\n    resultsCloseBtn.ZIndex = 11\n    resultsCloseBtn.Parent = resultsModal\n    createCorner(resultsCloseBtn, 10)\n    refs.ResultsCloseBtn = resultsCloseBtn\n\n    -- =========================================================================\n    -- 6. CENTER: COSMETIC SHOP MODAL\n    -- =========================================================================\n    local shopModal = Instance.new(\"Frame\")\n    shopModal.Name = \"ShopModal\"\n    shopModal.Size = UDim2